    char buffer[256];
    FILE *file = fopen("/proc/self/fd/0", "r");
    if (file == NULL) {
        perror("fopen");
        return 1;
    }
    if (fread(buffer, 1, 256, file)!= 256) {
        perror("fread");
        return 1;
